"use strict";
// Síntesis y ejemplos originales de NeuroNova Apps, fundamentados en CAST (2024).
// Índices por numeración oficial DUA 3.0.
window.DUA_DETAILS={
guidelines:{
1:["Percepción","Ofrecer información perceptible por distintas vías y con opciones que permitan ajustar su presentación.","Permitir ajustar tamaño de letra y acompañar un contenido visual con una descripción accesible."],
2:["Lenguaje y los símbolos","Facilitar la comprensión de palabras, códigos, estructuras y símbolos, atendiendo a la diversidad lingüística.","Explicar términos nuevos con ejemplos, glosario visual y apoyos para interpretar símbolos matemáticos."],
3:["Construcción del conocimiento","Relacionar saberes, reconocer ideas centrales y facilitar que lo aprendido se utilice en otros contextos.","Activar conocimientos previos y comparar ejemplos para aplicar una idea a un problema nuevo."],
4:["Interacción","Ofrecer formas accesibles de responder, desplazarse y utilizar materiales y herramientas.","Permitir participar mediante teclado, comunicación aumentativa o materiales manipulables."],
5:["Expresión y comunicación","Abrir diferentes vías para comunicar ideas y crear productos, con apoyo que aumente gradualmente la autonomía.","Ofrecer respuestas orales, escritas o visuales cuando todas evidencien el mismo aprendizaje."],
6:["Desarrollo de estrategias","Ayudar a fijar metas, anticipar dificultades, organizar recursos y revisar el progreso.","Proponer una meta comprensible y una lista de verificación para ajustar el plan."],
7:["Acoger intereses e identidades","Diseñar experiencias conectadas con las identidades, intereses y decisiones de los aprendices, cuidando su seguridad y participación.","Ofrecer temas de investigación entre los que cada estudiante pueda escoger sin cambiar la meta."],
8:["Mantener el esfuerzo y la persistencia","Hacer claras las metas, graduar el desafío y fomentar apoyo mutuo, pertenencia y retroalimentación útil.","Dividir un proyecto en etapas con metas visibles y devoluciones que orienten el siguiente intento."],
9:["Capacidad emocional","Favorecer el reconocimiento de las emociones, la reflexión, la empatía y las condiciones que ayudan a aprender.","Iniciar la sesión con una elección de estrategia de regulación y cerrar revisando cómo funcionó."]
},
considerations:{
"1.1":["Ajustar la forma de presentar la información a preferencias y necesidades de acceso.","Ofrecer control sobre tamaño del texto, contraste y velocidad de reproducción."],
"1.2":["Combinar maneras de acceder a la información para que una sola vía sensorial no se convierta en obstáculo.","Proporcionar descripción verbal de imágenes y texto de apoyo a explicaciones orales."],
"1.3":["Seleccionar materiales donde distintas comunidades y experiencias aparezcan representadas con respeto.","Utilizar relatos y ejemplos de diversos contextos culturales sin reducirlos a estereotipos."],
"2.1":["Hacer explícitos los términos y estructuras que pueden impedir comprender el contenido.","Presentar palabras clave con definiciones claras y ejemplos contextualizados."],
"2.2":["Incorporar apoyos para interpretar textos y códigos sin que la decodificación oculte la meta central.","Utilizar lectura asistida y guías para comprender signos y expresiones matemáticas."],
"2.3":["Reconocer la diversidad de lenguas y dialectos como recurso para aprender y comunicarse.","Permitir comparar expresiones en distintas variedades lingüísticas con una actitud de respeto."],
"2.4":["Revisar si las palabras y símbolos elegidos transmiten prejuicios o invisibilizan experiencias.","Analizar un enunciado y reemplazar expresiones discriminatorias por formulaciones respetuosas."],
"2.5":["Combinar formas de representación para aclarar conceptos y relaciones.","Explicar una secuencia con palabras, diagrama y demostración práctica."],
"3.1":["Activar saberes previos y conectarlos de modo explícito con el contenido nuevo.","Preguntar qué conocen sobre un fenómeno antes de examinar una explicación nueva."],
"3.2":["Hacer visibles las características y relaciones esenciales, diferenciándolas de detalles secundarios.","Marcar patrones comunes entre ejemplos y elaborar un mapa de relaciones."],
"3.3":["Reconocer diferentes experiencias y formas de construir significados durante el aprendizaje.","Contrastar una explicación científica con observaciones y saberes de la comunidad."],
"3.4":["Diseñar oportunidades para aplicar lo aprendido en contextos diferentes.","Tras resolver un problema con apoyo, plantear otro en una situación cotidiana."],
"4.1":["Diversificar los modos de interactuar para reducir barreras de movimiento, navegación o respuesta.","Ofrecer alternativas a una actividad que requiere exclusivamente escribir a mano o correr."],
"4.2":["Asegurar acceso efectivo a herramientas y materiales accesibles cuando sean necesarios.","Probar el uso de lectores de pantalla, pulsadores o recursos manipulativos antes de la sesión."],
"5.1":["Permitir distintos medios de comunicar una idea cuando sean coherentes con la meta.","Aceptar una narración grabada, un texto o una secuencia ilustrada para explicar una historia."],
"5.2":["Facilitar herramientas variadas para elaborar producciones y expresar creatividad.","Permitir crear un informe con procesador de texto, audio o una presentación visual."],
"5.3":["Ofrecer práctica y apoyos graduados que se retiren progresivamente según el progreso.","Modelar una exposición, practicar con una guía y luego disminuir las ayudas."],
"5.4":["Examinar expectativas injustas sobre qué formas de expresión se consideran válidas.","Valorar la calidad de las ideas sin penalizar un modo de comunicación que no forma parte de la meta."],
"6.1":["Ayudar a formular metas comprensibles y relevantes para la actividad.","Acordar qué se quiere lograr y cómo reconocer el avance al finalizar."],
"6.2":["Anticipar obstáculos y elegir estrategias antes de comenzar.","Planificar pasos alternativos si falta un material o aparece una dificultad."],
"6.3":["Facilitar el manejo de los datos, materiales y tiempos que requiere la tarea.","Usar carpetas, organizadores y una secuencia breve de pasos."],
"6.4":["Proporcionar evidencias para reconocer avances y ajustar decisiones.","Revisar una rúbrica sencilla a mitad del trabajo y decidir qué mejorar."],
"6.5":["Cuestionar reglas y prácticas que restringen injustificadamente la participación.","Revisar si un único formato de entrega excluye a quienes podrían demostrar la misma competencia de otro modo."],
"7.1":["Brindar elecciones relevantes para la meta y posibilidades reales de decidir.","Dejar escoger entre temas o herramientas accesibles para desarrollar una misma competencia."],
"7.2":["Conectar las actividades con propósitos reconocibles y experiencias significativas.","Vincular una actividad matemática con una situación del entorno del grupo."],
"7.3":["Integrar oportunidades de exploración, curiosidad y juego apropiadas al propósito de aprendizaje.","Utilizar un desafío lúdico que permita ensayar y volver a intentar."],
"7.4":["Reconocer condiciones y prejuicios que generan inseguridad o desvían la participación.","Establecer acuerdos de respeto y revisar materiales que representen de forma estereotipada a un grupo."],
"8.1":["Explicar para qué se aprende algo y cómo se reconocerá el logro.","Mostrar un ejemplo del producto esperado y conversar sobre la utilidad de la meta."],
"8.2":["Ajustar la dificultad y los apoyos sin eliminar oportunidades de aprendizaje valiosas.","Proporcionar pistas opcionales para abordar un problema progresivamente más complejo."],
"8.3":["Crear oportunidades de aprender con otros mediante cooperación y responsabilidad compartida.","Asignar roles flexibles y permitir que el grupo construya una respuesta común."],
"8.4":["Favorecer que cada integrante del grupo se sienta reconocido y pueda participar.","Invitar a acordar formas de ayuda mutua y comprobar que todas las voces tienen espacio."],
"8.5":["Dar información concreta que ayude a decidir qué hacer después.","Señalar un avance y proponer un siguiente paso verificable en vez de limitarse a una nota."],
"9.1":["Ayudar a reconocer cómo las expectativas y las creencias influyen en la disposición para aprender.","Conversar sobre qué estrategia se espera que funcione y por qué."],
"9.2":["Desarrollar conciencia de emociones, necesidades propias y experiencias de los demás.","Utilizar una escala simple para reconocer cómo se siente el grupo ante una actividad."],
"9.3":["Ofrecer momentos para revisar individual y colectivamente procesos y decisiones.","Cerrar un proyecto con preguntas sobre lo que ayudó y lo que convendría cambiar."],
"9.4":["Crear condiciones de empatía y reparación cuando se producen tensiones o daños.","Facilitar un diálogo respetuoso para reconocer efectos de un conflicto y acordar cómo repararlo."]
}
};

/* Desarrollo original y ampliado de la Directriz 7 basado en las capturas
   compartidas y las páginas oficiales de CAST (2024). No reproduce su texto. */
window.DUA_EXPANDED={
"7":{
 paragraphs:[
 "Los intereses y las identidades influyen en cómo las personas se vinculan con las actividades educativas. Para facilitar el compromiso, conviene conocer aquello que cada estudiante considera significativo, los recursos que utiliza y las condiciones en las que puede participar con seguridad.",
 "La identidad puede relacionarse con la lengua, la cultura, las experiencias, la discapacidad y las comunidades de pertenencia, entre otras dimensiones. Ninguna de estas características permite anticipar por sí sola qué motivará a un estudiante: sus intereses también cambian con el tiempo.",
 "Acoger intereses e identidades implica diseñar alternativas flexibles que reconozcan a cada aprendiz como participante legítimo, sin exigir que todos aprendan mediante los mismos temas, materiales o formas de intervención."
 ],
 actions:[
 "Conocer las preferencias de los estudiantes sin asumir que todos los miembros de un grupo comparten los mismos intereses.",
 "Revisar ejemplos y materiales para incluir experiencias diversas representadas de manera respetuosa.",
 "Ofrecer distintas vías de participación vinculadas con una meta de aprendizaje común.",
 "Mantener espacios donde cada estudiante pueda expresar qué condiciones favorecen o dificultan su participación."
 ],
 example:"Al planificar un proyecto sobre el entorno, el docente ofrece varias preguntas de investigación relacionadas con la comunidad. Los estudiantes escogen una, proponen materiales accesibles y acuerdan cómo compartir sus hallazgos.",
 url:"https://udlguidelines.cast.org/es/compromiso/intereses-identidades/"
},
"7.1":{
 paragraphs:[
 "La autonomía se fortalece cuando el estudiante puede tomar decisiones que realmente inciden en cómo aprende. Las opciones deben guardar relación con la meta de aprendizaje y ser posibles de utilizar con los apoyos disponibles.",
 "Dar a elegir no equivale a abandonar al aprendiz frente a demasiadas alternativas. Algunas personas preferirán seleccionar entre dos opciones claras; otras podrán proponer nuevas rutas o participar en la planificación de las actividades. La elección puede cambiar según el contexto y el momento."
 ],
 actions:[
 "Permitir escoger entre contenidos o temas que conduzcan al mismo propósito de aprendizaje.",
 "Ofrecer varias herramientas para investigar, elaborar una respuesta o presentar una producción.",
 "Acordar opciones para practicar, revisar o mostrar el progreso.",
 "Flexibilizar, cuando corresponda, el orden de los pasos y los tiempos de trabajo.",
 "Invitar a los estudiantes a participar en decisiones sobre metas y tareas sin imponerles más elecciones de las que desean asumir."
 ],
 example:"En una actividad de narración, cada estudiante elige entre crear una secuencia ilustrada, grabar el relato o escribirlo. El docente mantiene como criterio común la organización del inicio, el desarrollo y el desenlace.",
 url:"https://udlguidelines.cast.org/es/compromiso/intereses-identidades/autonom%C3%ADa-elecci%C3%B3n/"
},
"7.2":{
 paragraphs:[
 "Las actividades suelen despertar mayor interés cuando su propósito resulta comprensible y conecta con experiencias, preguntas o metas significativas para quien aprende. Esa conexión puede surgir tanto de situaciones cotidianas como de relatos imaginarios y problemas creativos.",
 "No existe un único tema valioso para todo el grupo. Conviene variar los contextos y permitir que los estudiantes identifiquen relaciones entre los contenidos escolares y sus vidas, comunidades o aspiraciones, sin reducir sus identidades a estereotipos."
 ],
 actions:[
 "Contextualizar temas y fuentes de información en realidades cercanas y culturalmente pertinentes.",
 "Proponer tareas con una finalidad visible y un destinatario, cuando esto sea adecuado.",
 "Ofrecer alternativas acordes con distintas edades, conocimientos previos y formas de participar.",
 "Incluir exploración, experimentación y oportunidades para utilizar la imaginación.",
 "Reservar momentos para que los estudiantes expliquen qué valor encuentran en la actividad y cómo la mejorarían."
 ],
 example:"Para estudiar las medidas, el grupo puede diseñar un pequeño huerto, elaborar una maqueta o planear la distribución de un aula. Cada opción requiere comparar longitudes y justificar decisiones.",
 url:"https://udlguidelines.cast.org/es/compromiso/intereses-identidades/relevancia-valor-autenticidad/"
},
"7.3":{
 paragraphs:[
 "El juego y la alegría pueden sostener la curiosidad y facilitar que las personas prueben estrategias sin temor a equivocarse. Las experiencias lúdicas pueden incluir movimiento, exploración sensorial, narraciones, creación artística y desafíos de descubrimiento.",
 "El modo de disfrutar una actividad no es igual para todos. Un juego competitivo puede motivar a algunos estudiantes y desanimar a otros; por ello es preferible ofrecer opciones de participación, ritmos y formas de interacción que permitan encontrar sentido y bienestar."
 ],
 actions:[
 "Crear oportunidades de juego simbólico, exploración libre o actividades artísticas relacionadas con la meta.",
 "Permitir experimentar y descubrir antes de pedir una respuesta definitiva.",
 "Ofrecer alternativas de participación individual o colaborativa cuando resulte pertinente.",
 "Utilizar historias y situaciones imaginativas para abrir posibilidades de aprendizaje.",
 "Reconocer los logros sin convertir toda la experiencia en una competencia."
 ],
 example:"En inicial, el grupo explora un mercado simulado con objetos, etiquetas y roles voluntarios. Puede contar productos, conversar sobre compras o inventar historias, con apoyos para distintas formas de comunicación.",
 url:"https://udlguidelines.cast.org/es/compromiso/intereses-identidades/juego-alegr%C3%ADa/"
},
"7.4":{
 paragraphs:[
 "Las barreras para el compromiso pueden aparecer cuando el ambiente resulta impredecible, excluyente o difícil de habitar: comentarios discriminatorios, temor a la evaluación pública, estímulos excesivos o instrucciones poco claras pueden apartar la atención de la meta educativa.",
 "El propósito no es eliminar cualquier desafío, sino identificar condiciones que generan riesgos innecesarios y ofrecer maneras de participar con seguridad y dignidad. El docente también debe revisar sus propias expectativas y estar abierto a la información que aportan los estudiantes sobre las barreras."
 ],
 actions:[
 "Conversar sobre prejuicios, trato respetuoso y situaciones que dificultan la participación.",
 "Hacer visibles rutinas, horarios, cambios y tiempos previstos mediante apoyos comprensibles.",
 "Ofrecer anticipación y opciones para manejar interrupciones o eventos inesperados.",
 "Ajustar ruido, iluminación, movimiento, pausas y duración de las actividades cuando resulte necesario.",
 "Revisar si el tipo de evaluación o exposición pública crea barreras evitables y proporcionar apoyos apropiados.",
 "Establecer acuerdos de aula y opciones de autorregulación para que los estudiantes puedan sentirse seguros."
 ],
 example:"Antes de una exposición, la docente anticipa el orden de participación y permite ensayar. Ofrece apoyos visuales, espacios con menos ruido y opciones de presentación equivalentes según la meta evaluada.",
 url:"https://udlguidelines.cast.org/es/compromiso/intereses-identidades/sesgos-amenazas-distracciones/"
},
"8":{"paragraphs":["Mantener el esfuerzo y la persistencia requiere metas comprensibles y condiciones que ayuden a continuar aprendiendo. La motivación puede variar según el contexto, el interés, el desafío y los apoyos disponibles.","El diseño educativo puede sostener el compromiso mediante objetivos con sentido, desafíos ajustados, colaboración, pertenencia y retroalimentación que oriente las acciones siguientes."],"actions":["Explicar qué se aprenderá y para qué.","Ajustar el desafío y proporcionar apoyos pertinentes.","Facilitar la colaboración y el sentido de comunidad.","Ofrecer comentarios oportunos sobre el proceso y los próximos pasos."],"example":"En un proyecto de varias semanas, la docente divide el trabajo en etapas, aclara criterios, organiza apoyos y reserva espacios de intercambio para que el grupo pueda revisar sus avances.","url":"https://udlguidelines.cast.org/es/"},
"8.1":{"paragraphs":["Una meta clara permite dirigir la atención y organizar el esfuerzo durante una tarea prolongada. El alumnado necesita comprender el propósito de lo que hace y reconocer cómo se relaciona con sus experiencias e intereses.","Retomar la meta a lo largo de la actividad ayuda a mantenerla presente, especialmente cuando surgen dificultades o se desarrollan varios pasos."],"actions":["Formular o reformular explícitamente la meta.","Presentarla de múltiples maneras accesibles.","Descomponer las metas amplias en objetivos parciales.","Ofrecer ejemplos que ayuden a imaginar el resultado esperado.","Relacionar el propósito con los contextos e intereses del grupo."],"example":"Antes de escribir una historia, la docente muestra una secuencia ilustrada con inicio, desarrollo y desenlace y acuerda con el grupo qué revisarán en cada etapa.","url":"https://udlguidelines.cast.org/es/"},
"8.2":{"paragraphs":["Los desafíos promueven el aprendizaje cuando existe una relación adecuada entre la dificultad, los recursos y los apoyos. Todos los estudiantes necesitan oportunidades exigentes, aunque no necesariamente los mismos caminos para abordarlas.","Ofrecer opciones de complejidad y andamiajes permite mantener expectativas de progreso sin convertir una barrera evitable en el centro de la actividad."],"actions":["Mantener expectativas de aprendizaje y reconocer el potencial de cada estudiante.","Ofrecer opciones con distintos niveles de complejidad.","Proporcionar herramientas y andamiajes vinculados con la meta.","Valorar el proceso, el esfuerzo y el progreso además del producto final."],"example":"En una actividad de resolución de problemas, se ofrecen materiales manipulativos, pistas graduales y preguntas guía que cada estudiante puede utilizar según su necesidad.","url":"https://udlguidelines.cast.org/es/"},
"8.3":{"paragraphs":["La colaboración permite crear conocimiento a partir de perspectivas y experiencias diversas. La interdependencia reconoce que pedir ayuda, contribuir y sostener a otros pueden formar parte del aprendizaje.","Para que el trabajo conjunto sea accesible, conviene acordar responsabilidades, hacer explícitas las formas de apoyo y ofrecer oportunidades reales de participación a todas las personas."],"actions":["Construir acuerdos de colaboración con el grupo.","Definir metas, roles y responsabilidades flexibles.","Explicar cómo solicitar y ofrecer ayuda.","Facilitar el intercambio respetuoso de diferentes perspectivas.","Promover tutorías entre pares y comunidades de aprendizaje.","Formular preguntas compartidas para profundizar la comprensión."],"example":"Durante una investigación, los integrantes de cada equipo eligen roles acordes con sus aportes y revisan conjuntamente cómo avanzar cuando aparece una dificultad.","url":"https://udlguidelines.cast.org/es/"},
"8.4":{"paragraphs":["La sensación de pertenecer a una comunidad de aprendizaje ayuda a sostener la participación. Un entorno donde las personas se sienten valoradas facilita compartir ideas, solicitar apoyo y afrontar dificultades.","La pertenencia puede tener distintos significados según las experiencias e identidades de los aprendices. Por ello, el grupo necesita oportunidades para construir relaciones, expresar perspectivas y reconocer barreras que producen exclusión."],"actions":["Crear espacios para conversar sobre qué hace que el aula sea acogedora.","Invitar a proponer prácticas que fortalezcan el sentido de comunidad.","Reconocer los intereses e identidades de los estudiantes.","Examinar momentos en que los sesgos pueden impedir la participación.","Cuidar que cada integrante tenga oportunidades de aportar."],"example":"La docente construye con el grupo acuerdos de convivencia y revisa periódicamente si las actividades y formas de participación permiten que todos sean escuchados.","url":"https://udlguidelines.cast.org/es/"},
"8.5":{"paragraphs":["La retroalimentación orientada a la acción ofrece información sobre el progreso y ayuda a identificar qué se puede hacer a continuación. Es más útil cuando se relaciona con la meta, llega a tiempo y se comprende.","Conviene poner el foco en estrategias, práctica y mejora, en vez de comparar a los estudiantes o emitir juicios generales sobre sus capacidades."],"actions":["Ofrecer comentarios concretos y accesibles.","Destacar estrategias utilizadas, esfuerzo y progreso.","Dar retroalimentación frecuente y oportuna.","Priorizar información sustantiva sobre comparaciones competitivas.","Modelar cómo usar una devolución para revisar y mejorar la tarea.","Abrir posibilidades para intentar una estrategia distinta."],"example":"Después de una exposición, la docente identifica un avance concreto, pregunta qué apoyo fue útil y propone un siguiente paso verificable para mejorar la comunicación.","url":"https://udlguidelines.cast.org/es/"},
"9":{"paragraphs":["Reconocer las propias emociones, comprender cómo influyen en las decisiones y responder con empatía forma parte de la capacidad emocional. Las emociones y el pensamiento intervienen conjuntamente en el aprendizaje; no corresponde exigir que una persona deje de sentir para poder aprender.","Los aprendices desarrollan estas capacidades de distintas maneras. Algunas personas avanzan observando modelos y ensayando estrategias; otras necesitan apoyos más explícitos para reconocer lo que sienten, anticipar dificultades y decidir cómo continuar.","El diseño del entorno debe ofrecer oportunidades de practicar la autorregulación, la reflexión y el cuidado mutuo, sin trasladar toda la responsabilidad de las barreras al estudiante."],"actions":["Proponer estrategias accesibles para identificar emociones y necesidades de apoyo.","Modelar formas de afrontar la frustración y otros desafíos emocionales.","Ofrecer oportunidades de reflexión individual y colectiva.","Reconocer que las necesidades de autorregulación varían entre personas y situaciones.","Revisar las condiciones del entorno que podrían generar malestar o exclusión."],"example":"Antes de realizar una actividad nueva, la docente anticipa lo que ocurrirá, presenta alternativas para pedir ayuda y facilita que el grupo elija una estrategia que le permita afrontar el desafío.","url":"https://udlguidelines.cast.org/es/"},
"9.1":{"paragraphs":["Las expectativas y creencias que cada estudiante tiene sobre sus posibilidades pueden influir en su motivación y en las metas que se propone. Conocer las propias fortalezas y dificultades permite formular propósitos alcanzables y reconocer el valor del esfuerzo.","El docente puede acompañar este proceso mediante metas personales, recordatorios y modelos de afrontamiento. También necesita examinar si sus expectativas implícitas generan barreras, por ejemplo, cuando se espera menos de algunos estudiantes o se interpreta el compromiso de una sola manera."],"actions":["Utilizar recordatorios, guías, rúbricas y listas de verificación para orientar metas personales.","Practicar estrategias para manejar frustración, ansiedad y distracciones ante los desafíos.","Ofrecer oportunidades de atención sostenida y autorreflexión graduadas.","Facilitar tutorías o modelos que enseñen cómo reconocer fortalezas y fijar metas realistas.","Revisar prejuicios y expectativas bajas que puedan limitar la participación."],"example":"Al iniciar un proyecto, cada estudiante elige una meta personal posible, identifica un apoyo que necesita y revisa con la docente los avances sin compararse con el resto del grupo.","url":"https://udlguidelines.cast.org/es/"},
"9.2":{"paragraphs":["Aprender a reconocer emociones y necesidades propias requiere práctica, modelos y ocasiones de reflexión. El apoyo no termina cuando se muestra una estrategia de autorregulación: los estudiantes necesitan ensayarla en situaciones diversas y valorar cuándo les resulta útil.","Esta consideración también comprende la conciencia social, es decir, la capacidad de atender a las perspectivas de otras personas. Los apoyos deben permitir comprender la diversidad de experiencias sin imponer una única manera de expresar emociones o afrontar dificultades."],"actions":["Ofrecer modelos y andamiajes para afrontar la frustración y pedir apoyo emocional.","Enseñar maneras de reconocer y revisar pensamientos que dificultan una tarea.","Practicar estrategias de afrontamiento mediante simulaciones y situaciones cotidianas.","Generar oportunidades para reflexionar sobre interacciones sociales.","Reconocer recursos personales, culturales y lingüísticos propios y de otras personas."],"example":"Tras un desacuerdo durante una actividad grupal, los estudiantes usan apoyos visuales o preguntas guía para identificar cómo se sintieron, escuchar otras perspectivas y elegir una forma respetuosa de continuar.","url":"https://udlguidelines.cast.org/es/"},
"9.3":{"paragraphs":["La reflexión individual y colectiva ayuda a reconocer avances, aprender de los errores y tomar decisiones sobre el siguiente intento. Las personas necesitan apoyos diferentes para observar su propio progreso y comprender cómo aprenden.","Disponer de instrumentos accesibles para autoevaluarse y recibir retroalimentación facilita reconocer qué estrategias funcionaron y qué se debe ajustar. Esta reflexión puede realizarse individualmente o junto con el grupo."],"actions":["Ofrecer instrumentos, gráficos o registros para recopilar y representar avances.","Utilizar plantillas, paneles o apoyos alternativos para revisar el progreso.","Proponer preguntas breves sobre dificultades, recursos utilizados y decisiones siguientes.","Incorporar momentos de autoevaluación y evaluación grupal.","Modelar cómo usar la información recopilada para ajustar las estrategias."],"example":"Al cerrar una secuencia de actividades, cada estudiante selecciona una evidencia de su progreso y el grupo conversa sobre qué apoyos facilitaron la tarea y qué modificarían la próxima vez.","url":"https://udlguidelines.cast.org/es/"},
"9.4":{"paragraphs":["La empatía favorece un entorno donde las personas pueden comprender perspectivas distintas y cuidar las relaciones. Es necesario que las experiencias y las identidades diversas estén representadas con respeto, de modo que los estudiantes tengan oportunidades de reconocer realidades diferentes de la propia.","Las prácticas restaurativas permiten responder a los conflictos atendiendo al impacto de las acciones, la responsabilidad compartida y la reparación. Su finalidad no es ignorar el daño, sino crear condiciones para reconocerlo, escucharse y reconstruir la convivencia de manera segura."],"actions":["Utilizar círculos de diálogo accesibles para compartir experiencias y perspectivas.","Facilitar maneras voluntarias y seguras de expresar necesidades emocionales y pedir apoyo.","Construir acuerdos de aula centrados en cuidado y responsabilidad comunitaria.","Enseñar procedimientos para reconocer el impacto de un conflicto y acordar acciones de reparación.","Invitar a familias y comunidad cuando sea pertinente y exista un propósito educativo claro.","Respetar los límites y la seguridad de quienes han sido afectados; no imponer reconciliaciones."],"example":"Ante un conflicto, la docente ofrece un espacio seguro para que las personas involucradas expliquen qué ocurrió y qué necesitan. Con acompañamiento, se acuerdan acciones concretas para reparar el daño y prevenir nuevas situaciones.","url":"https://udlguidelines.cast.org/es/"},
"1":{"paragraphs":["Para aprender, la información esencial debe poder percibirse. Si se ofrece mediante una sola vía sensorial o en un formato difícil de utilizar, se crean barreras que pueden impedir la comprensión aunque el estudiante tenga conocimientos y motivación para participar.","Diseñar opciones para la percepción significa presentar información relevante a través de distintas modalidades y permitir que su formato se adapte a las necesidades de acceso. También supone incluir perspectivas diversas y representaciones respetuosas de personas y comunidades.","No se trata de multiplicar materiales sin propósito, sino de conservar el significado de lo que se enseña y ofrecer alternativas equivalentes, accesibles y comprensibles."],"actions":["Combinar texto, voz, imágenes descritas, materiales táctiles u otras modalidades pertinentes para una misma meta.","Permitir ajustes de presentación como tamaño del texto, contraste, volumen o velocidad de reproducción.","Verificar que gráficos, videos, sonidos y documentos tengan alternativas accesibles.","Seleccionar materiales que representen distintas historias, identidades y experiencias sin estereotipos.","Consultar con los estudiantes qué formatos funcionan y corregir barreras detectadas."],"example":"Al explicar el ciclo del agua, la docente combina una explicación oral, un esquema con descripción, texto legible y una representación manipulativa. El grupo puede acceder al contenido por diferentes vías y demostrar su comprensión con apoyos adecuados.","url":"https://udlguidelines.cast.org/es/"},
"1.1":{"paragraphs":["Personalizar la presentación permite que una misma información sea legible, perceptible y manejable para diferentes aprendices. Un formato fijo puede generar barreras evitables: una letra pequeña, poco contraste o un audio demasiado rápido pueden dificultar el acceso al contenido.","Los materiales digitales pueden facilitar ajustes, pero no son accesibles por el simple hecho de estar en pantalla. Deben diseñarse para que sus controles, su estructura y su contenido sean utilizables con distintas tecnologías de apoyo y preferencias de presentación."],"actions":["Permitir modificar el tipo y tamaño de letra, el espaciado, el ancho de línea y la disposición del contenido.","Ofrecer alternativas de color de fondo, color de texto y contraste suficiente.","Facilitar el ajuste de tamaño de imágenes, diagramas y tablas sin perder información esencial.","Permitir controlar volumen, velocidad y reproducción de materiales sonoros.","Ofrecer controles de tiempo y velocidad de videos, animaciones o simulaciones.","Revisar el orden y la disposición de elementos para que la navegación sea comprensible y accesible."],"example":"En una lectura digital, cada estudiante puede ampliar la fuente y ajustar el contraste. La docente proporciona también una versión imprimible legible y verifica que el documento pueda recorrerse con teclado y lector de pantalla.","url":"https://udlguidelines.cast.org/es/"},
"1.2":{"paragraphs":["Las imágenes, los sonidos, los gráficos y los textos no son igualmente accesibles para todas las personas. Ofrecer múltiples formas de percibir la información permite evitar que una sola modalidad determine quién puede participar en el aprendizaje.","Las alternativas deben comunicar la información importante, no limitarse a duplicar un archivo. Una descripción de un gráfico ha de explicar sus relaciones; una transcripción debe recoger el mensaje oral relevante, y los avisos sonoros necesitan señales que también puedan percibirse de otra manera.","Los apoyos pueden variar según el contexto: algunas personas utilizan audio, otras texto, lengua de señas, modelos físicos o recursos táctiles. El objetivo es que puedan acceder al significado de la actividad."],"actions":["Acompañar imágenes, gráficos, animaciones y videos con descripciones significativas.","Proporcionar objetos reales, maquetas o representaciones táctiles cuando aporten al propósito educativo.","Explicar oralmente los conceptos y relaciones esenciales representados de forma visual.","Ofrecer subtítulos, transcripciones o alternativas textuales al material auditivo.","Utilizar apoyos visuales y recursos lingüísticos accesibles para instrucciones y alertas sonoras.","Comprobar la accesibilidad de la lectura en voz alta y evitar depender de un único medio."],"example":"En una clase sobre formas geométricas, el docente combina figuras en relieve, descripción oral, láminas contrastadas y texto accesible. Para un video de apoyo, ofrece subtítulos y una transcripción.","url":"https://udlguidelines.cast.org/es/"},
"1.3":{"paragraphs":["La percepción también incluye la posibilidad de reconocerse en el currículo y conocer experiencias distintas de la propia. Los materiales influyen en qué historias, comunidades y formas de vivir se consideran visibles y valiosas en el entorno educativo.","Una selección limitada de autores, imágenes o ejemplos puede reforzar estereotipos o presentar una perspectiva particular como si fuera universal. Representar identidades de maneras auténticas exige diversidad y atención a la complejidad de las personas y sus contextos.","Las representaciones respetuosas favorecen que los estudiantes exploren diferentes puntos de vista, cuestionen generalizaciones y construyan vínculos más significativos con los contenidos."],"actions":["Incluir autoras, autores y voces con distintas experiencias, identidades, culturas y situaciones de discapacidad.","Reconocer aportes de comunidades y personas diversas al conocimiento trabajado.","Revisar cómo aparecen representadas las personas y culturas en textos, imágenes y ejemplos.","Evitar caricaturas, relatos únicos y generalizaciones sobre grupos humanos.","Buscar perspectivas complejas y contextualizadas que permitan comparar diferentes miradas.","Facilitar espacios de escucha y diálogo respetuoso entre experiencias diversas."],"example":"Al trabajar relatos de la comunidad, la docente incluye textos y testimonios de autores locales, personas con discapacidad y familias con experiencias diversas, y propone analizar cómo cada historia amplía la comprensión del entorno.","url":"https://udlguidelines.cast.org/es/"},
"2":{"paragraphs":["Las personas difieren en su familiaridad con palabras, signos, fórmulas, imágenes y otras formas de representar información. Lo que aclara una idea para alguien puede resultar difícil de interpretar para otra persona por su experiencia, lengua o conocimientos previos.","Cuando se utiliza una única forma de representar el lenguaje y los símbolos, aparecen barreras para la comprensión. Ofrecer representaciones alternativas permite aclarar significados y construir relaciones compartidas sin considerar una variedad lingüística o forma de expresión como inferior."],"actions":["Identificar vocabulario, signos y estructuras que requieren una explicación adicional.","Combinar formas lingüísticas, gráficas, orales, táctiles y visuales según el propósito de la actividad.","Ofrecer apoyos para interpretar textos, números, símbolos y fórmulas.","Reconocer las lenguas y variedades lingüísticas de los estudiantes.","Revisar si los materiales usan expresiones excluyentes o representaciones poco claras."],"example":"Al presentar un problema matemático, el docente explica los signos, muestra una representación con objetos y propone una versión verbal de la relación numérica para facilitar la comprensión.","url":"https://udlguidelines.cast.org/es/"},
"2.1":{"paragraphs":["Las palabras, los números, los símbolos y las estructuras del lenguaje pueden necesitar aclaraciones diferentes según la experiencia del aprendiz. Suponer que todos comparten el mismo vocabulario puede impedir que comprendan la información esencial.","No basta con definir términos aislados: también conviene explicar relaciones entre ideas, expresiones figuradas, estructuras de oraciones y notaciones que pueden resultar poco familiares."],"actions":["Anticipar el vocabulario y los símbolos clave conectándolos con experiencias y conocimientos previos.","Añadir descripciones textuales a símbolos e íconos gráficos.","Mostrar cómo se forman términos y expresiones complejas a partir de unidades más simples.","Ofrecer glosarios, definiciones contextuales, ilustraciones y traducciones accesibles.","Aclarar expresiones idiomáticas, tecnicismos y referencias culturales poco familiares.","Explicitar la estructura de oraciones, ecuaciones, diagramas y textos mediante ejemplos y organizadores."],"example":"Antes de leer un texto sobre el ecosistema, el grupo explora palabras clave mediante imágenes descritas, definiciones sencillas y un mapa de conceptos; la docente explica cómo se relacionan las ideas.","url":"https://udlguidelines.cast.org/es/"},
"2.2":{"paragraphs":["Interpretar con fluidez palabras, números y signos requiere práctica; mientras se desarrolla esa familiaridad, la decodificación puede consumir atención que el estudiante necesita para comprender el contenido.","Cuando la habilidad para leer un código no constituye el objetivo que se evalúa, es pertinente ofrecer formas alternativas de acceder a la información sin renunciar a la enseñanza progresiva de ese código."],"actions":["Proporcionar lectura asistida o tecnologías de texto a voz cuando sean apropiadas.","Ofrecer representaciones accesibles de notaciones matemáticas digitales.","Combinar texto digital con grabaciones o lectura en voz alta.","Presentar expresiones matemáticas mediante palabras, fórmulas y gráficos cuando corresponda.","Ofrecer aclaraciones breves de notación y listas de términos clave.","Verificar que los apoyos tecnológicos sean utilizables por quienes los necesitan."],"example":"En una actividad sobre fracciones, el docente presenta 1/2 en notación matemática, con una figura dividida en dos partes y una explicación verbal; el estudiante practica la notación sin perder el significado de la relación.","url":"https://udlguidelines.cast.org/es/"},
"2.3":{"paragraphs":["Los grupos educativos reúnen personas que utilizan diferentes lenguas y dialectos. Si todo el material supone que una sola variedad lingüística es la única legítima, se pueden crear obstáculos para acceder al contenido y participar.","Cultivar la comprensión entre lenguas también significa reconocer que los conocimientos lingüísticos del estudiante son recursos para aprender. Las traducciones, ejemplos multilingües y apoyos no lingüísticos deben facilitar la comunicación, no reemplazar ni desvalorizar la lengua de origen."],"actions":["Incluir obras y relatos de distintos contextos lingüísticos y culturales.","Facilitar momentos para compartir lenguas, expresiones e historias de las comunidades.","Ofrecer términos clave con equivalencias, pronunciación y definiciones pertinentes.","Usar glosarios multilingües y herramientas de traducción con revisión humana cuando sea necesaria.","Apoyar el uso flexible de más de una lengua durante la construcción de significado.","Reconocer las lenguas de señas y otras formas de comunicación.","Combinar explicaciones lingüísticas con apoyos visuales o materiales accesibles."],"example":"Al estudiar plantas locales, el grupo compara sus denominaciones en castellano y lenguas de la comunidad, utiliza imágenes con descripciones y registra conocimientos aportados por las familias.","url":"https://udlguidelines.cast.org/es/"},
"2.4":{"paragraphs":["Algunas formas de hablar, escribir o representar información se presentan como superiores a otras. Estas jerarquías pueden generar barreras para quienes utilizan otras lenguas o dialectos y afectar su sentido de pertenencia.","Abordar los sesgos exige revisar el lenguaje explícito y las ideas implícitas de los materiales y las interacciones. Enseñar una variedad académica no requiere invalidar las demás ni equiparar diferencia lingüística con falta de capacidad."],"actions":["Escuchar y valorar distintas lenguas y dialectos en situaciones educativas.","Ofrecer subtítulos, lengua de señas y apoyos multilingües cuando corresponda.","Etiquetar materiales en varios idiomas si eso ayuda al grupo.","Promover diferentes formas de comunicación oral, escrita o signada.","Evitar expresiones capacitistas, discriminatorias o deshumanizantes.","Analizar junto al grupo cómo ciertas palabras y símbolos transmiten prejuicios.","Explicar los usos del lenguaje académico sin desacreditar las formas de hablar de las comunidades."],"example":"Durante una revisión de textos, la docente diferencia el registro requerido para una carta formal de las expresiones propias del habla familiar, sin calificar estas últimas como inferiores.","url":"https://udlguidelines.cast.org/es/"},
"2.5":{"paragraphs":["Cuando el contenido se presenta solo como texto, algunas relaciones o procesos pueden ser difíciles de comprender. Combinar medios ofrece otras maneras de explorar los conceptos y construir significado.","Las imágenes, simulaciones, objetos, narraciones y gráficos deben complementar la información y explicitar las conexiones importantes, en vez de funcionar como adornos que aumenten la carga de interpretación."],"actions":["Representar conceptos clave mediante ilustraciones, esquemas, modelos, fotografías o materiales manipulativos.","Incorporar videos, simulaciones o demostraciones accesibles cuando ayuden a explicar un proceso.","Aclarar cómo se conectan la explicación escrita y los gráficos que la acompañan.","Ofrecer descripciones y alternativas perceptibles de la información visual.","Seleccionar los medios a partir de la meta y de las barreras identificadas."],"example":"Para explicar la germinación, la docente utiliza semillas reales, una secuencia ilustrada con descripciones y una narración breve que relaciona las etapas observadas.","url":"https://udlguidelines.cast.org/es/"},
"3":{"paragraphs":["La información accesible se convierte en conocimiento cuando los estudiantes la relacionan, interpretan y utilizan activamente. Construir significado implica recuperar saberes previos, reconocer lo esencial, formular preguntas y poner en práctica ideas en situaciones variadas.","El conocimiento también se construye en colaboración: las perspectivas, experiencias y formas de interpretar el mundo de otras personas pueden enriquecer la comprensión. Por ello conviene ofrecer distintas vías para procesar la información y apoyos que hagan visible cómo se conectan los conceptos.","El propósito de esta directriz es facilitar que el aprendizaje resulte útil más allá de una actividad puntual, respetando la diversidad de experiencias y los apoyos que cada estudiante requiere."],"actions":["Activar y reconocer los conocimientos previos pertinentes.","Destacar patrones, características fundamentales y relaciones entre ideas.","Combinar modelos, relatos, problemas y experiencias para construir significado.","Crear ocasiones de diálogo y elaboración colectiva del conocimiento.","Ofrecer apoyos para recordar y aplicar lo aprendido en contextos nuevos."],"example":"En un proyecto sobre el agua, el grupo comparte experiencias del entorno, observa modelos, identifica relaciones entre fenómenos y aplica sus conclusiones a una situación cotidiana de su comunidad.","url":"https://udlguidelines.cast.org/es/"},
"3.1":{"paragraphs":["Comprender una idea nueva suele requerir conectarla con saberes y experiencias anteriores. Cuando un estudiante no dispone del conocimiento de base necesario, o no identifica su relación con la actividad, puede encontrar barreras aunque la explicación sea clara.","El docente puede explorar lo que el grupo ya conoce, ofrecer apoyos para recuperar información relevante y enseñar conceptos previos que resulten imprescindibles. También es útil vincular experiencias de diferentes áreas y contextos."],"actions":["Explorar experiencias y conocimientos previos mediante preguntas, imágenes descritas o situaciones prácticas.","Usar organizadores previos, mapas conceptuales y rutinas de activación de saberes.","Enseñar o modelar conceptos de base antes de introducir información más compleja.","Construir analogías que conecten ideas nuevas con situaciones conocidas.","Explicitar relaciones entre áreas de aprendizaje y experiencias del entorno."],"example":"Antes de trabajar los estados del agua, la docente pregunta qué ocurre al congelar o calentar líquidos y utiliza esas experiencias para relacionar los conceptos de sólido, líquido y gaseoso.","url":"https://udlguidelines.cast.org/es/"},
"3.2":{"paragraphs":["Las personas con experiencia en un tema suelen identificar con mayor facilidad sus patrones e ideas importantes. Quienes están empezando pueden concentrarse en detalles secundarios o no advertir cómo se relacionan los elementos esenciales.","Señalar de manera explícita las características críticas y comparar ejemplos ayuda a organizar la información y a construir conexiones con los conocimientos previos. Los apoyos deben guiar la atención sin reemplazar la exploración del estudiante."],"actions":["Destacar elementos relevantes en textos, gráficos, diagramas o fórmulas accesibles.","Usar esquemas y organizadores que hagan visibles las relaciones principales.","Comparar ejemplos y contraejemplos para distinguir características importantes.","Introducir señales que dirijan la atención hacia ideas esenciales.","Mostrar cómo aplicar una habilidad ya conocida a un problema nuevo."],"example":"Al enseñar figuras geométricas, el docente compara triángulos de diferentes tamaños y posiciones con otras figuras para ayudar a reconocer que tienen tres lados, independientemente de su apariencia.","url":"https://udlguidelines.cast.org/es/"},
"3.3":{"paragraphs":["Las personas construyen significado mediante experiencias y formas de conocer diversas. Junto con los procedimientos secuenciales, también aportan valor la narración, la resolución colaborativa de problemas, la exploración corporal, las relaciones con el entorno y otros saberes culturales.","Ofrecer diferentes entradas al contenido permite aprovechar esas experiencias sin asumir que existe una única manera legítima de comprender. Los apoyos pueden ayudar a organizar la información, explorar conexiones y disminuir la sobrecarga que generan tareas complejas."],"actions":["Combinar narración, exploración, resolución de problemas y aprendizaje interpersonal cuando sean pertinentes.","Explicitar pasos de los procesos que requieren secuencias complejas.","Ofrecer tablas, modelos, organizadores y estrategias alternativas para procesar información.","Incorporar recursos interactivos que permitan probar ideas y construir nuevas relaciones.","Graduar los apoyos y presentar la información en unidades manejables.","Proponer distintas rutas para recorrer el contenido y retirar distracciones innecesarias."],"example":"Para estudiar un ecosistema, el grupo puede escuchar relatos locales, observar un modelo, comparar datos en una tabla y construir colectivamente un mapa de las relaciones entre los seres vivos.","url":"https://udlguidelines.cast.org/es/"},
"3.4":{"paragraphs":["Aprender un contenido no garantiza que resulte sencillo utilizarlo en otras situaciones. La transferencia se facilita cuando el estudiante reconoce las relaciones entre lo ya conocido y el nuevo contexto, recuerda estrategias útiles y tiene oportunidades para practicarlas de manera deliberada.","Las personas necesitan diferentes apoyos para recuperar conocimientos y generalizarlos. Los recordatorios, esquemas y ejemplos variados pueden acompañar el proceso hasta que las estrategias se utilicen de forma progresivamente más autónoma."],"actions":["Ofrecer listas de verificación, recordatorios y organizadores accesibles.","Enseñar estrategias para recuperar información, como imágenes clave o paráfrasis.","Practicar una misma habilidad en situaciones y materiales diversos.","Vincular contenidos nuevos con mapas conceptuales, analogías y conocimientos previos.","Proponer situaciones guiadas donde se aplique lo aprendido fuera del ejemplo inicial.","Retomar las ideas con el tiempo y conversar sobre cómo utilizarlas en otros contextos."],"example":"Después de aprender a medir longitudes con una regla, los estudiantes utilizan la misma estrategia para comparar materiales del aula y planificar las dimensiones de una pequeña maqueta.","url":"https://udlguidelines.cast.org/es/"},
"4":{"paragraphs":["Los materiales educativos y los espacios de aprendizaje pueden imponer una única manera de desplazarse, responder o utilizar herramientas. Las páginas impresas, los controles que requieren mouse y la disposición rígida del mobiliario pueden dificultar la participación de quienes interactúan de otras formas.","Las necesidades de navegación y respuesta cambian según la persona y la actividad. Diseñar para la interacción significa ofrecer rutas equivalentes para acceder a materiales, orientarse y mostrar lo que se sabe, con tecnologías de apoyo y alternativas físicas disponibles.","Una interacción accesible no debe reducir innecesariamente el desafío académico: conviene distinguir entre la habilidad que se desea aprender y el movimiento o dispositivo que exige el material."],"actions":["Revisar si las tareas requieren de manera innecesaria un único movimiento, dispositivo o velocidad.","Ofrecer diferentes formas de navegación, selección y respuesta.","Organizar el espacio físico para permitir rutas accesibles y alternativas de ubicación.","Probar la compatibilidad de materiales digitales con herramientas de asistencia.","Conservar las metas de aprendizaje al modificar la forma de interactuar."],"example":"En una actividad de clasificación, los estudiantes pueden mover tarjetas, indicar la respuesta oralmente, utilizar un pulsador o seleccionar elementos mediante teclado. La meta sigue siendo identificar correctamente las categorías.","url":"https://udlguidelines.cast.org/es/"},
"4.1":{"paragraphs":["Los estudiantes no interactúan con el entorno ni responden de una sola manera. Las exigencias de ritmo, tiempo, desplazamiento y precisión motora pueden convertirse en barreras cuando son ajenas a la meta educativa.","Valorar diferentes métodos de respuesta y movimiento implica ofrecer opciones reales y revisar la organización del aula, la ergonomía y los controles de los materiales, de modo que la participación no dependa exclusivamente de lápiz, mouse o una postura determinada."],"actions":["Flexibilizar tiempos, ritmo, velocidad y rango de movimiento cuando el objetivo lo permita.","Ofrecer respuestas mediante voz, escritura, selección, señalamiento u otros medios pertinentes.","Facilitar interacción física con la mano, pulsadores, joystick, teclado convencional o adaptado.","Permitir alternativas a controles exclusivos de mouse o lápiz y papel.","Revisar disposición y altura del mobiliario, ubicación de materiales e iluminación."],"example":"Durante un circuito de habilidades, una estudiante puede recorrer una ruta accesible y demostrar coordinación mediante lanzamientos adaptados; se evalúa la habilidad prevista y no solamente la rapidez al desplazarse.","url":"https://udlguidelines.cast.org/es/"},
"4.2":{"paragraphs":["Los recursos accesibles y las tecnologías de asistencia pueden ampliar las oportunidades de acceso, participación y progreso. No basta con disponer de una herramienta: debe funcionar con los materiales concretos, estar integrada en la actividad y responder a las preferencias del aprendiz.","Algunas personas necesitan teclado, voz, pulsadores o apoyos de movilidad para utilizar una actividad digital o física. Ofrecer estos medios contribuye a que la navegación y la producción no dependan de un único dispositivo o mecanismo.","El uso de apoyos de accesibilidad debe facilitar la participación plena sin disminuir de manera injustificada las expectativas o el nivel de aprendizaje."],"actions":["Verificar que una interfaz pueda recorrerse con teclado, mouse y dispositivos de entrada alternativos cuando corresponda.","Facilitar comandos de teclado equivalentes a las acciones que exigen mouse.","Comprobar el acceso a teclados alternativos, en pantalla o adaptados.","Permitir opciones de interacción por voz o pulsadores cuando sean necesarias.","Seleccionar aplicaciones compatibles con las herramientas de asistencia utilizadas por los estudiantes.","Probar los recursos con sus usuarios antes de emplearlos en una actividad importante."],"example":"En una práctica de crucigramas digitales, el docente comprueba que todas las casillas puedan seleccionarse mediante teclado y que un estudiante pueda introducir respuestas con su dispositivo de entrada adaptado.","url":"https://udlguidelines.cast.org/es/"},
"5":{"paragraphs":["No existe un medio de expresión que resulte igualmente adecuado para todas las personas ni para todas las metas. Un formato único puede dificultar que determinados estudiantes comuniquen conocimientos que sí han construido.","Diseñar opciones para la expresión y la comunicación implica distinguir la meta de aprendizaje del medio empleado para demostrarla. Cuando el formato no es el objetivo de la actividad, ofrecer medios equivalentes puede reducir barreras sin modificar lo que se espera aprender."],"actions":["Ofrecer distintas maneras de expresar conocimientos e ideas cuando la meta lo permita.","Facilitar herramientas variadas para construir, componer y crear.","Incorporar práctica y apoyos que se retiren gradualmente.","Examinar si ciertos modos de expresión son desvalorizados sin justificación pedagógica.","Mantener criterios de evaluación relacionados con el aprendizaje esperado."],"example":"Para comunicar propuestas de cuidado ambiental, el alumnado puede producir una narración grabada, un texto ilustrado o una presentación accesible; en todos los casos debe explicar y sustentar sus propuestas.","url":"https://udlguidelines.cast.org/es/"},
"5.1":{"paragraphs":["Ofrecer varias maneras de comunicarse puede ampliar la participación cuando no existe una razón pedagógica para imponer un único formato. La elección del medio debe responder a la intención comunicativa, el contenido y la audiencia.","La variedad de formas de expresión permite reconocer prácticas comunicativas históricamente poco valoradas y ampliar las oportunidades para desarrollar composición y comunicación, no únicamente escritura."],"actions":["Ofrecer texto, narración oral, dibujo, cómic, fotografía, música, video o movimiento cuando sean pertinentes.","Incorporar materiales manipulativos que permitan representar ideas y relaciones.","Facilitar herramientas digitales accesibles para comunicar y colaborar.","Enseñar a seleccionar el medio apropiado para el mensaje y el destinatario.","Valorar las producciones por los criterios de la meta y no por una preferencia arbitraria de formato."],"example":"En una narración, el estudiante puede escribir un cuento, grabarlo o elaborar una historieta que evidencie inicio, nudo y desenlace.","url":"https://udlguidelines.cast.org/es/"},
"5.2":{"paragraphs":["Las posibilidades de crear y comunicar dependen en parte de las herramientas disponibles. Un entorno centrado en pocos recursos puede limitar la participación de personas cuyas formas de trabajar y expresarse son diferentes.","El repertorio de herramientas debe ser flexible y accesible. Los recursos digitales, incluida la inteligencia artificial cuando sea pertinente, requieren una selección crítica: su utilidad depende de si favorecen el aprendizaje y preservan la agencia del estudiante, no de su novedad."],"actions":["Ofrecer correctores, predicción de palabras, dictado y grabación de audio cuando aporten a la meta.","Utilizar organizadores gráficos, guiones, mapas conceptuales y plantillas.","Facilitar herramientas para diseño, composición, animación o presentaciones accesibles.","Permitir calculadoras, materiales matemáticos y geometría dinámica cuando corresponda.","Combinar recursos digitales con herramientas físicas o manipulativas.","Enseñar a elegir y evaluar las herramientas en función de la tarea."],"example":"Para explicar un proceso científico, los estudiantes pueden utilizar una maqueta, un mapa conceptual digital o una presentación narrada, con herramientas elegidas en función de sus necesidades y de la meta.","url":"https://udlguidelines.cast.org/es/"},
"5.3":{"paragraphs":["La fluidez se desarrolla mediante la práctica, el ensayo, el acompañamiento y la retroalimentación. Las personas pueden requerir distintos andamiajes para explorar, producir y mostrar lo que saben.","Los apoyos deben poder adaptarse y retirarse gradualmente según el progreso, sin convertir la independencia inmediata en requisito para participar. La evaluación formativa permite identificar cuándo mantener, modificar o reducir una ayuda."],"actions":["Proponer modelos que muestren varias estrategias para alcanzar un mismo resultado.","Incorporar tutorías, mentoría y ejemplos guiados.","Facilitar andamiajes ajustables que puedan retirarse de forma progresiva.","Dar retroalimentación accesible durante la práctica.","Ofrecer oportunidades de ensayo, revisión y nueva presentación.","Valorar el proceso de aprendizaje junto con el producto final."],"example":"Antes de exponer, un estudiante observa modelos, practica con una guía visual y recibe comentarios concretos. En sucesivos ensayos decide cuáles apoyos conserva y cuáles ya no necesita.","url":"https://udlguidelines.cast.org/es/"},
"5.4":{"paragraphs":["Los prejuicios pueden hacer que ciertos modos de expresión y comunicación reciban menos reconocimiento que otros. La preferencia automática por el texto escrito o por una variedad lingüística puede invisibilizar conocimientos y experiencias.","Diseñar para la diversidad requiere revisar cómo se eligen, presentan y evalúan los medios comunicativos. Si varios formatos permiten demostrar la misma meta, no corresponde tratarlos como inferiores por diferencias culturales, lingüísticas o de accesibilidad."],"actions":["Analizar si existen prejuicios en los formatos permitidos para expresarse.","Revisar si la evaluación favorece un medio que no es parte de la meta.","Reconocer la comunicación oral, signada, visual, escrita y multimodal cuando sea pertinente.","Explicar por qué diferentes modos alineados con el propósito son válidos.","Escuchar a los estudiantes sobre las barreras que encuentran al comunicar sus ideas."],"example":"En una actividad de argumentación, el docente admite respuestas grabadas, signadas con apoyo de video o escritas y utiliza los mismos criterios de calidad del razonamiento para todas.","url":"https://udlguidelines.cast.org/es/"},
"6":{"paragraphs":["El desarrollo de estrategias ayuda a que los estudiantes actúen con intención, formulen metas, anticipen obstáculos, organicen recursos y revisen el efecto de sus decisiones. Estas habilidades no aparecen necesariamente de manera espontánea ni se desarrollan al mismo ritmo en todas las personas.","El diseño educativo puede liberar recursos cognitivos mediante apoyos para tareas iniciales y, a la vez, proporcionar andamiajes específicos para planificar, tomar decisiones y evaluar el progreso. La meta es aumentar la capacidad para utilizar estrategias, no exigir autonomía sin ofrecer las condiciones para construirla.","Las oportunidades de planificación y seguimiento también deben ser inclusivas: si las rutinas, materiales o criterios generan barreras injustificadas, corresponde examinarlos y modificarlos."],"actions":["Enseñar a formular metas significativas y reconocibles.","Reservar tiempo para anticipar dificultades y organizar un plan.","Ofrecer organizadores, guías y recursos externos para manejar la información.","Dar oportunidades para revisar avances y ajustar estrategias.","Identificar y cuestionar prácticas del entorno que limitan la participación."],"example":"Para desarrollar una investigación, la docente ayuda a definir la meta, ofrece una plantilla de planificación, permite registrar fuentes en un organizador y propone revisiones periódicas para modificar los pasos si aparecen dificultades.","url":"https://udlguidelines.cast.org/es/"},
"6.1":{"paragraphs":["Una meta significativa permite comprender hacia dónde se dirige una actividad y tomar decisiones sobre el esfuerzo, el tiempo y los recursos necesarios. Debe expresar un propósito valioso y desafiante, pero también ser suficientemente clara para reconocer el progreso.","Establecer metas no equivale a fijarlas sin ayuda. Algunos estudiantes necesitarán ejemplos, preguntas guía o apoyos visuales para estimar los pasos y formular objetivos alcanzables."],"actions":["Presentar modelos que muestren cómo se formula una meta y cómo se reconoce su logro.","Utilizar preguntas guía para estimar esfuerzo, recursos y nivel de desafío.","Ofrecer plantillas o listas de verificación para definir metas comprensibles.","Hacer visibles las metas y los cronogramas en formatos accesibles.","Revisar si una meta requiere ajustes conforme avanza la actividad."],"example":"Al iniciar un proyecto de lectura, el estudiante acuerda una meta concreta, identifica los materiales que utilizará y registra en una lista cómo verificará que ha comprendido el texto.","url":"https://udlguidelines.cast.org/es/"},
"6.2":{"paragraphs":["Una vez establecida la meta, planificar exige anticipar pasos, recursos y dificultades posibles. Sin tiempo ni apoyos para organizar el proceso, algunos estudiantes pueden encontrar barreras antes de comenzar o al enfrentar un imprevisto.","Los andamiajes para la planificación enseñan a dividir una tarea compleja, seleccionar prioridades y considerar alternativas. La práctica guiada ayuda a construir estrategias que pueden emplearse progresivamente con mayor autonomía."],"actions":["Utilizar preguntas para anticipar dificultades y posibles respuestas.","Mostrar en voz alta o de forma visual cómo una persona organiza su procedimiento.","Ofrecer listas de pasos y plantillas de planificación de proyectos.","Facilitar acompañamiento de pares, tutores o docentes que modelen la planificación.","Dividir metas de largo plazo en objetivos parciales alcanzables.","Permitir revisar el plan cuando cambian las condiciones o aparecen nuevas necesidades."],"example":"Antes de construir una maqueta, el grupo elabora una lista de materiales, ordena las tareas, distribuye responsabilidades y acuerda qué hará si falta algún recurso.","url":"https://udlguidelines.cast.org/es/"},
"6.3":{"paragraphs":["La memoria de trabajo permite mantener temporalmente información mientras se realiza una tarea. Cuando la actividad exige recordar demasiados datos o instrucciones a la vez, puede resultar difícil organizar ideas y resolver problemas.","Los apoyos externos, como esquemas, plantillas y registros accesibles, ayudan a conservar información relevante sin que toda la carga recaiga en la memoria del aprendiz. Deben apoyar la comprensión y el manejo de recursos, no sustituir el trabajo intelectual que forma parte de la meta."],"actions":["Ofrecer organizadores gráficos y plantillas para recoger y ordenar información.","Facilitar categorías y preguntas que ayuden a reconocer temas y patrones.","Utilizar listas de verificación de materiales y pasos.","Proporcionar guías breves para tomar apuntes o registrar decisiones.","Permitir consultar instrucciones mientras se desarrolla la actividad."],"example":"Durante una actividad de ciencias, los estudiantes registran observaciones en una tabla con categorías y utilizan una lista visible de pasos para comparar resultados sin tener que memorizar todas las instrucciones.","url":"https://udlguidelines.cast.org/es/"},
"6.4":{"paragraphs":["Reconocer cuánto se ha avanzado respecto de una meta facilita decidir si conviene mantener o modificar la estrategia. Para ello, la retroalimentación debe resultar comprensible, oportuna y relacionada con los criterios de aprendizaje.","El seguimiento puede apoyarse en registros visuales, rúbricas, listas de verificación y momentos de reflexión. Es útil que las personas dispongan de distintas formas de observar el proceso y seleccionar aquellas que mejor se ajusten a sus necesidades."],"actions":["Usar preguntas guía para promover la autorregulación y revisar decisiones.","Representar el progreso mediante gráficos, fotografías, tablas o portafolios accesibles.","Explorar formatos de retroalimentación acordes con las metas y preferencias del grupo.","Ofrecer plantillas de autoevaluación sobre la calidad y la completitud de una tarea.","Modelar estrategias diferentes para evaluar lo realizado.","Facilitar rúbricas, listas de verificación y ejemplos de desempeño."],"example":"A mitad de una producción escrita, el estudiante compara su borrador con una rúbrica sencilla, identifica qué ya logró y decide el siguiente cambio con apoyo de la docente.","url":"https://udlguidelines.cast.org/es/"},
"6.5":{"paragraphs":["Las normas y prácticas del entorno pueden impedir la participación de estudiantes cuyas experiencias, formas de comunicación o necesidades de apoyo no fueron consideradas al planificar. Desafiar las prácticas excluyentes implica reconocer que algunas barreras se encuentran en el diseño y no en la persona.","El análisis debe abrir oportunidades para escuchar a quienes viven esas barreras, cuestionar las decisiones que las mantienen y acordar cambios concretos. Cuando una práctica ha causado daño, las acciones de reparación deben priorizar la seguridad y la dignidad de las personas afectadas."],"actions":["Dedicar espacios periódicos a revisar la participación y las barreras identificadas.","Recoger experiencias individuales y colectivas sobre situaciones de exclusión.","Analizar qué reglas, formatos o expectativas generan dificultades innecesarias.","Construir y poner en práctica cambios específicos con la comunidad educativa.","Ofrecer vías seguras de reparación cuando se identifique daño, sin imponer reconciliación.","Comprobar si los cambios realizados mejoran efectivamente el acceso y la participación."],"example":"Al advertir que una entrega obligatoriamente manuscrita impide a varios estudiantes mostrar lo aprendido, el equipo docente revisa la exigencia y permite formatos accesibles equivalentes, manteniendo los criterios del contenido evaluado.","url":"https://udlguidelines.cast.org/es/"}
};
